package hearthborn.l10n;

import java.util.function.Supplier;

/**
 * Translation scope for text generated by server-provided attribute tooltip code.
 *
 * @author Jagy2014
 */
public final class TooltipText {
    private static final ThreadLocal<Boolean> capped = new ThreadLocal<>();
    private static final ThreadLocal<Boolean> active = new ThreadLocal<>();
    public static String translate(String text) {
        if(!Boolean.TRUE.equals(active.get()) || text == null || text.isEmpty()) return text;
        if(text.indexOf('\n') >= 0) {
            String[] lines = text.split("\\n", -1);
            for(int i=0;i<lines.length;i++) lines[i]=translate(lines[i]);
            return String.join("\n",lines);
        }
        String trimmed = text.trim();
        if(trimmed.isEmpty()) return text;
        int at = text.indexOf(trimmed);
        return text.substring(0, at) + phrase(trimmed) + text.substring(at + trimmed.length());
    }

    /** Render a name that must stay in its original language. */
    public static <T> T literal(Supplier<T> render) {
        Boolean previous = active.get();
        active.set(false);
        try { return render.get(); }
        finally { if(previous == null) active.remove(); else active.set(previous); }
    }

    private static String phrase(String trimmed) {
        int start = 0, end = trimmed.length();
        while(start < end && !Character.isLetter(trimmed.charAt(start))) start++;
        while(end > start && !Character.isLetter(trimmed.charAt(end - 1))) end--;
        if(start == end) return trimmed;
        String core = trimmed.substring(start, end);
        if(!core.matches(".*[A-Za-z].*")) return trimmed;
        if(core.equals("Value ceiling")) capped.set(true);
        String translated = hearthborn.L10n.find("tooltip", core);
        if(translated == null && core.indexOf(':') >= 0)
            translated = hearthborn.L10n.find("label", core);
        if(translated == null) translated = hearthborn.L10n.text("tooltip", core);
        if(translated.equals(core)) return trimmed;
        return trimmed.substring(0, start) + translated + trimmed.substring(end);
    }
    public static java.awt.image.BufferedImage attribute(java.util.function.Supplier<java.awt.image.BufferedImage> render) {
        Boolean previous = capped.get();
        capped.set(false);
        try {
            java.awt.image.BufferedImage image = render(render);
            if(image != null && Boolean.TRUE.equals(capped.get())) {
                haven.Text hint = haven.Text.std.renderwrap(hearthborn.L10n.tr(
                    "Raise the base value to use more of your bonuses."),
                    new java.awt.Color(180, 180, 165), image.getWidth());
                image = haven.ItemInfo.catimgs(haven.UI.scale(6), image, hint.img);
            }
            return image;
        } finally { if(previous == null) capped.remove(); else capped.set(previous); }
    }

    public static <T> T render(Supplier<T> render) {
        Boolean previous = active.get();
        active.set(true);
        try { return render.get(); }
        finally { if(previous == null) active.remove(); else active.set(previous); }
    }
}
